function fetchUserData(userId) {
  return new Promise((resolve, reject) => {
    if (!userId || userId <= 0) {
      reject(new Error("Invalid user ID"));
      return;
    }
    setTimeout(() => {
      resolve({
        id: userId,
        name: `User ${userId}`,
        email: `user${userId}@example.com`
      });
    }, 500);
  });
}

function getUserWithOrders(userId) {
  return fetchUserData(userId)
    .then(user => {
      return new Promise(resolve => {
        setTimeout(() => {
          resolve({ userId, orders: [{ id: 1, total: 99.99 }] });
        }, 300);
      });
    })
    .then(orders => ({
      user: { id: userId, name: `User ${userId}` },
      orders: orders.orders
    }));
}

function fetchAllUsers(userIds) {
  return Promise.all(userIds.map(id => fetchUserData(id)));
}

function fetchWithRetry(fn, retries = 3, delay = 1000) {
  return fn().catch(err => {
    if (retries <= 0) throw err;
    return new Promise(resolve => setTimeout(resolve, delay))
      .then(() => fetchWithRetry(fn, retries - 1, delay));
  });
}

function fetchWithTimeout(promise, timeout) {
  const timeoutPromise = new Promise((_, reject) =>
    setTimeout(() => reject(new Error("Request timed out")), timeout)
  );
  return Promise.race([promise, timeoutPromise]);
}
